{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    total_capacity = sum(s['capacity'] for s in segments)
    total_minimum = sum(s['minimum'] for s in segments)
    if budget < total_minimum or budget > total_capacity:
        raise ValueError('Budget infeasible')
    n = len(segments)
    allocations = [s['minimum'] for s in segments]
    used_budget = sum(allocations)
    remaining = budget - used_budget
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, s in enumerate(segments):
            if allocations[i] >= s['capacity']:
                continue
            ratio = s['importance'] / (allocations[i] + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            raise ValueError('Cannot allocate remaining budget (segments full)')
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"
}
